(()=>{window.SpanAssetsReady=Promise.all(['room-empty-v10','room-terrace-v11','dining-sofa-v10','sofa-modular-v10','parent-work-v12','people-v10','child-v11','oak-grain-v6'].map(name=>{const im=new Image();im.src='assets/'+name+'.webp';return im.decode().catch(()=>{});}));const $=id=>document.getElementById(id);const defs=`<pattern id="oakPhoto" width="300" height="18" y="-6" patternUnits="userSpaceOnUse"><image href="data:image/webp;base64," width="300" height="200" y="-6"/></pattern><linearGradient id="weightMetal" x2="1" y2="1"><stop stop-color="#c5ced0"/><stop offset=".45" stop-color="#a4b0b4"/><stop offset="1" stop-color="#75878f"/></linearGradient><linearGradient id="timber" x2="0" y2="1"><stop stop-color="#e9d6b5"/><stop offset=".5" stop-color="#d7bb91"/><stop offset="1" stop-color="#c1a078"/></linearGradient><linearGradient id="steel"><stop stop-color="#8797a0"/><stop offset=".35" stop-color="#e5eaeb"/><stop offset=".55" stop-color="#a9b5bc"/><stop offset="1" stop-color="#667d8c"/></linearGradient><linearGradient id="glass" x2="0" y2="1"><stop stop-color="#cee0e6"/><stop offset="1" stop-color="#f2eee0"/></linearGradient><radialGradient id="light"><stop stop-color="#fff4cf" stop-opacity=".8"/><stop offset="1" stop-color="#fff4cf" stop-opacity="0"/></radialGradient><filter id="contact"><feGaussianBlur stdDeviation="2"/></filter><pattern id="grain" width="70" height="9" patternUnits="userSpaceOnUse"><path d="M0 2Q18 0 35 2T70 2M0 6Q28 3 49 6T80 6" fill="none" stroke="#9d784d" stroke-opacity=".19" stroke-width=".5"/></pattern>`;$('board').querySelector('defs').insertAdjacentHTML('beforeend',defs);$('board').querySelector(':scope > rect').setAttribute('fill','#f4f2ed');
function beam(a,b,bad,added){const len=Math.hypot(b.x-a.x,b.y-a.y),ang=Math.atan2(b.y-a.y,b.x-a.x)*180/Math.PI;return `<g class="model-member ${added?'removable':'fixed-member'}" data-removable="${!!added}" transform="translate(${a.x},${a.y}) rotate(${ang})"><path d="M2 10H${len+2}" stroke="#243a43" opacity=".16" stroke-width="8"/><path d="M0 7H${len}v5H0Z" fill="#8f714e"/><rect y="-9" width="${len}" height="18" rx="1" fill="#d8bd94"/><rect y="-9" width="${len}" height="18" rx="1" fill="url(#oakPhoto)"/><rect y="-9" width="${len}" height="18" fill="#9e6933" opacity=".08"/><path d="M0-9h${len}l-2-2H2Z" fill="#efe0c5"/><path d="M0-8v17m${len}-17v17" stroke="#9d815d" stroke-width="2"/><path d="M3-8H${len-3}" stroke="#fff7e7" stroke-opacity=".75"/><path d="M3 8H${len-3}" stroke="#a88960" stroke-width=".6"/>${[7,len-16].map(x=>`<rect x="${x}" y="-9" width="9" height="18" rx=".7" fill="url(#steel)" stroke="#7d8889" stroke-width=".5"/><circle cx="${x+4.5}" cy="0" r="2.2" fill="#eef0eb" stroke="#69797d" stroke-width=".7"/><path d="M${x+3.4} 0h2.2" stroke="#647279" stroke-width=".7"/>`).join('')}${added?`<path d="M20 7H${len-20}" stroke="${bad?'#b77927':'#0f235f'}" stroke-width="1.8" opacity=".8"/>`:''}${bad?`<rect y="-9" width="${len}" height="18" fill="#e7a843" opacity=".4"/>`:''}</g>`;}
function room(stage,success){const file=['empty-v10','empty-v10','terrace-v11','empty-v10'][stage],x=stage?25:27,w=stage?340:238,y=stage?215:220,h=stage?175:158;return '<svg x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" viewBox="0 140 1536 790" preserveAspectRatio="xMidYMax slice"><image class="room-photo" href="assets/room-'+file+'.webp" width="1536" height="1024"/></svg><ellipse class="room-light" cx="'+(stage?190:145)+'" cy="287" rx="'+(stage?110:75)+'" ry="70" fill="url(#light)" opacity="'+(success?.12:0)+'"/>';}
window.SpanVisual={render({p,c,stage,edges,sim,result,mode,selected}){let success=mode==='result'&&result?.success;$('living').removeAttribute('clip-path');if($('living').dataset.scene!==String(stage)){$('living').innerHTML=room(stage,false);$('living').dataset.scene=String(stage);}$('living').querySelector('.room-light')?.setAttribute('opacity',success?'.12':'0');$('living').setAttribute('opacity','1');$('members').innerHTML=[...c.base,...c.locked,...edges].map(([a,b])=>beam(p[a],p[b],sim&&[a,b].some(i=>Math.hypot(p[i].x-c.nodes[i].x,p[i].y-c.nodes[i].y)>9),edges.some(e=>SpanPhysics.key(...e)===SpanPhysics.key(a,b)))).join('');$('supports').innerHTML=[0,2].map(i=>`<path d="M${p[i].x-11} ${p[i].y+5}h22V367h-22Z" fill="#dedbd2"/><path d="M${p[i].x+11} ${p[i].y+5}l7-5V361l-7 6Z" fill="#b9bcb6"/><path d="M${p[i].x-11} ${p[i].y+5}l7-5h22l-7 5Z" fill="#f1eee5"/><path d="M${p[i].x-17} 367h34v6h-34Z" fill="#aab6ba"/><path d="M${p[i].x-8} ${p[i].y+11}V358" stroke="#f5f2e8" stroke-width="2"/>`).join('');const all=[...c.base,...c.locked,...edges],valid=SpanPhysics.candidates(stage).filter(e=>!all.some(x=>SpanPhysics.key(...x)===SpanPhysics.key(...e)));$('joints').innerHTML=c.visible.map(i=>{const v=p[i],fixed=c.nodes[i].fixed,sel=selected===i,can=mode==='edit'&&(selected===null?valid.some(e=>e.includes(i)):valid.some(e=>e.includes(i)&&e.includes(selected))),bad=result?.badNodes.includes(i)&&mode==='result';if(success)return `<g transform="translate(${v.x},${v.y})"><path d="M-13-9h26v21h-26Z" fill="#3a454a" opacity=".16" transform="translate(1 2)"/><rect x="-13" y="-10" width="26" height="21" rx="2" fill="url(#steel)" stroke="#69777c" stroke-width=".7"/><path d="M-11-9h22" stroke="#f9f6ed" stroke-width=".8"/>${[-8,8].map(x=>`<circle cx="${x}" cy="0" r="2.6" fill="#ebeeeb" stroke="#5c686e" stroke-width=".8"/><path d="M${x-1.3} 0h2.6" stroke="#647279" stroke-width=".7"/>`).join('')}</g>`;return `<g data-node="${i}" role="button" tabindex="${mode==='test'||mode==='transition'||success?-1:0}" aria-label="${fixed?'支点':'接続点'}${i}" aria-pressed="${sel}" transform="translate(${v.x},${v.y})"><circle r="${Math.max(31,22/$('board').getScreenCTM().a)}" fill="transparent"/><g opacity="${can||sel||mode!=='edit'?1:.55}">${fixed?'<rect x="-14" y="-12" width="28" height="28" rx="2" fill="url(#steel)" stroke="#718088"/><path d="M-10-8h3m14 0h3M-10 12h3m14 0h3" stroke="#5e6b70" stroke-width="2"/>':'<circle cy="2" r="15" fill="#33424b" opacity=".2"/>'}<circle r="14" fill="url(#steel)" stroke="#60737e" stroke-width=".7"/><circle r="11" fill="${sel?'#0f235f':can?'#0f235f':'#89979b'}" stroke="#f5f3e9" stroke-width="1.4"/>${can||sel?`<circle class="${sel?'selected-socket':''}" r="${sel?21:18}" fill="none" stroke="${sel?'#c49e50':'#0f235f'}" stroke-width="${sel?4:2.5}"/>`:''}${sel?'<path d="M-5 0l3 3 7-7" stroke="#ffe4a7" stroke-width="2.5" fill="none"/>':can?'<path d="M-5 0h10M0-5v10" stroke="#fff" stroke-width="2"/>':'<circle r="3.8" fill="#c4ced0" stroke="#64727b"/><path d="M-2 0h4" stroke="#65747b"/>'}${bad?'<circle r="22" fill="none" stroke="#bf842e" stroke-width="3"/>':''}</g></g>`;}).join('');
$('weights').innerHTML=c.loads.map((i,k)=>{const tick=sim?.tick||0,arrival=sim?Math.max(0,Math.min(1,(tick-SpanPhysics.MODEL.loadDelay-(k?180:0))/35)):0,base=p[i].y-20,y=base-31-(sim?(1-arrival)*13:0),current=mode==='test'&&arrival<1&&(k===0||tick>SpanPhysics.MODEL.loadDelay+150);return `<g opacity="${sim?(.55+.45*arrival):.7}"><ellipse cx="${p[i].x}" cy="${base+1}" rx="16" ry="2.7" fill="#233448" opacity="${.22*arrival}"/><g transform="translate(${p[i].x},${y})"><path d="M-13 6h26v23q-13 5-26 0Z" fill="url(#steel)" stroke="#75868c" stroke-width=".5"/><ellipse cy="6" rx="13" ry="3" fill="#e0e3df" stroke="#8a989c" stroke-width=".5"/><path d="M-4 5v-9h8v9" fill="url(#steel)" stroke="#7b8b91" stroke-width=".7"/><rect x="-8" y="-8" width="16" height="5" rx="1" fill="url(#steel)" stroke="#849196" stroke-width=".5"/><path d="M-10 10v16m2-15v15" stroke="#f1eee4" opacity=".45" stroke-width=".7"/><path d="M-10 29q10 3 20 0" stroke="#6b7980" opacity=".7"/>${current?'<path d="M0-27v12m-4-4 4 4 4-4" fill="none" stroke="#0f235f" stroke-width="2.5"/>':''}</g>${success?`<g transform="translate(${p[i].x+22},${p[i].y-40})"><circle r="9" fill="#0f235f" stroke="#fff" stroke-width="1.5"/><path d="M-4 0l3 3 5-6" fill="none" stroke="white" stroke-width="2"/></g>`:''}</g>`;}).join('');const roof=c.roof,pts=offset=>roof.map(i=>`${p[i].x},${p[i].y+offset}`).join(' ');$('roof').innerHTML=`<polygon points="${pts(-20)} ${roof.slice().reverse().map(i=>`${p[i].x},${p[i].y-9}`).join(' ')}" fill="#465b67"/><polygon points="${pts(-20)} ${roof.slice().reverse().map(i=>`${p[i].x+6},${p[i].y-26}`).join(' ')}" fill="#7d8e94"/><polyline points="${pts(-20)}" stroke="${success?'#c9ab64':'#a9b6b9'}" stroke-width="${success?3:1.5}" fill="none"/>`;}}
})();
